import{_ as n,o,c as d,a5 as c}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"for i in range(2, int(n0.5) + 1)","description":"这行代码是在判断一个数 n 是否为素数时使用的，它的作用是遍历从2到 n 的平方根（向下取整后再加1）的所有整数。遍历的目的是查看 n 是否能被这些数整除。如果 n 能被这些数中的任何一个整除，那么 n 不是素数；否则， n 是素数。 为什么只遍历到 n 的平方根 当你在判断一个。","frontmatter":{"title":"for i in range(2, int(n0.5) + 1)","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"这行代码是在判断一个数 n 是否为素数时使用的，它的作用是遍历从2到 n 的平方根（向下取整后再加1）的所有整数。遍历的目的是查看 n 是否能被这些数整除。如果 n 能被这些数中的任何一个整除，那么 n 不是素数；否则， n 是素数。 为什么只遍历到 n 的平方根 当你在判断一个。","sidebarWeight":5,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/HJ28 素数伴侣/for i in range(2, int(n0.5) + 1).md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/HJ28 素数伴侣/for i in range(2, int(n0.5) + 1).md","filePath":"posts/前端面试与实战/03-算法训练/HJ28 素数伴侣/for i in range(2, int(n0.5) + 1).md"}'),a={name:"posts/前端面试与实战/03-算法训练/HJ28 素数伴侣/for i in range(2, int(n0.5) + 1).md"};function t(i,e,r,s,_,l){return o(),d("div",null,[...e[0]||(e[0]=[c('<div><h1 id="for-i-in-range-2-int-n0-5-1" tabindex="-1">for i in range(2, int(n0.5) + 1) <a class="header-anchor" href="#for-i-in-range-2-int-n0-5-1" aria-label="Permalink to &quot;for i in range(2, int(n0.5) + 1)&quot;">​</a></h1><blockquote><p>本节目标：理解“for i in range(2, int(n0.5) + 1)”的核心思路，并能把它用于实际开发或面试表达。 这行代码是在判断一个数<code>n</code>是否为素数时使用的，它的作用是遍历从2到<code>n</code>的平方根（向下取整后再加1）的所有整数。遍历的目的是查看<code>n</code>是否能被这些数整除。如果<code>n</code>能被这些数中的任何一个整除，那么<code>n</code>不是素数；否则，<code>n</code>是素数。</p></blockquote><h3 id="为什么只遍历到n的平方根" tabindex="-1">为什么只遍历到<code>n</code>的平方根 <a class="header-anchor" href="#为什么只遍历到n的平方根" aria-label="Permalink to &quot;为什么只遍历到`n`的平方根&quot;">​</a></h3><p>当你在判断一个数是否为素数时，你只需要检查到该数的平方根即可。原因在于，如果<code>n</code>不是素数，它必然有一个因数在其平方根的范围内（即如果<code>n = a * b</code>，则<code>a</code>和<code>b</code>中至少有一个小于等于<code>n</code>的平方根）。这是因为如果<code>n</code>的所有因数都大于它的平方根，那么它们相乘的结果会超过<code>n</code>，这与假设<code>n</code>不是素数矛盾。因此，检查到<code>n</code>的平方根就足够了，这可以显著减少计算量。</p><h3 id="为什么要加1" tabindex="-1">为什么要加1 <a class="header-anchor" href="#为什么要加1" aria-label="Permalink to &quot;为什么要加1&quot;">​</a></h3><p>这里加1的原因是为了确保平方根被包含在遍历的范围内。当<code>n</code>的平方根是一个整数时，直接使用<code>int(n**0.5)</code>会得到平方根，但是在<code>range</code>函数中，结束的值是不包含在内的。为了确保平方根也被检查（特别是当平方根自身就是一个因数时），我们需要在<code>int(n**0.5)</code>的基础上加1，这样<code>range</code>函数的上限就包含了<code>n</code>的平方根。</p><p>例如，如果<code>n</code>是49，那么<code>n</code>的平方根是7。不加1的话，遍历的范围就是<code>range(2, 7)</code>，即2到6，7不会被包括在内。但是7是49的一个因数，因此我们需要遍历到7。通过加1，遍历的范围变为<code>range(2, int(49**0.5) + 1)</code>，即2到7，这样就能正确地检查到7了。</p><p>综上所述，这行代码是在素数判断函数中，通过遍历到<code>n</code>的平方根（包含平方根本身）来查找<code>n</code>的因数，从而判断<code>n</code>是否为素数的高效方式。加1是为了确保包含平方根这个可能的因数在遍历的范围内。</p></div>',1)])])}const g=n(a,[["render",t]]);export{p as __pageData,g as default};
